};
scwin.inputCalendar2_onviewchange = function(info) {
    console.log(info.oldValue + " " + info.newValue);
};
scwin.inputCalendar2_ondateselect = function(dateStr, dateObj) {
    console.log(dateStr);
};
scwin.calendar2_onclick = function(e) {
    console.log("click");
};
scwin.inputCalendar13_ondateselect = function(dateStr, dateObj) {
    if (dateStr) {
        console.log(dateStr);
        inputCalendar13.disableBeforeDate(dateStr);
    }
};
scwin.inputCalendar14_ondateselect = function(dateStr, dateObj) {
    if (dateStr) {
        inputCalendar14.disableAfterDate(dateStr);
    }
};
scwin.trigger1_onclick = function(e) {
