};
scwin.__checkCal = function() {
    var b = true
    ;((j) => j.length ? j : $('#mf_inputCalendar15_calendar_content table tbody td'))($('#inputCalendar15_calendar_content table tbody td')).each(function(i, el) {
        if (scwin.__getJq(el).text() >= "11" && (scwin.__getJq(el).text() <= "27") && scwin.__getJq(el).hasClass("w2calendar_date_on")) {
            if (scwin.__getJq(el).hasClass("w2calendar_date_disable")) {
                console.log(1);
                console.log(el);
                b = false;
            }
        } else {
            if (!scwin.__getJq(el).hasClass("w2calendar_date_disable")) {
                b = false;
            }
        }
    });
    return b;
}
scwin.onpageload2 = function() {
